window.REPORT_PRELOAD_CACHE["SPOT.html"] = {"version":"05701af27fec5fdede960a48fa8218e0579dcc9921601ff8e77def74c37205a1","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Spotify Technology S.A. (NYSE: SPOT) 深度研究报告：从全球流媒体音频霸主到高利润“AI 驱动型全品类音频与创作者平台”</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n    tailwind.config = {\n        darkMode: 'class',\n        theme: {\n            extend: {\n                fontFamily: {\n                    sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n                    mono: ['JetBrains Mono', 'monospace'],\n                },\n                colors: {\n                    navy: {\n                        950: '#070B14',\n                        900: '#0F172A',\n                        800: '#1E293B',\n                        700: '#334155',\n                    },\n                    spotgreen: {\n                        400: '#1ED760',\n                        500: '#1DB954',\n                        600: '#169C46',\n                    },\n                    accent: {\n                        500: '#3B82F6',\n                        600: '#2563EB',\n                    },\n                    teal: {\n                        500: '#06B6D4',\n                        600: '#0891B2',\n                    }\n                }\n            }\n        }\n    }\n    </script>\n\n    <style>\n    ::-webkit-scrollbar {\n        width: 6px;\n        height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n        background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n        background: #94A3B8;\n        border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n        background: #475569;\n    }\n\n    @media print {\n        #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n            display: none !important;\n        }\n        main {\n            margin-left: 0 !important;\n            padding: 0 !important;\n        }\n        section {\n            break-inside: avoid;\n        }\n    }\n\n    .report-card {\n        transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n        transform: translateY(-2px);\n    }\n\n    .nav-link.active {\n        background: linear-gradient(90deg, rgba(29, 185, 84, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n        border-left: 3px solid #1DB954;\n        color: #FFFFFF;\n        font-weight: 600;\n    }\n    </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-spotgreen-500 selection:text-white transition-colors duration-200\">\n\n    <!-- 顶部全局阅读进度条 -->\n    <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n        <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-spotgreen-500 via-emerald-400 to-teal-500 w-0 transition-all duration-150\"></div>\n    </div>\n\n    <!-- 移动端顶部导航栏 -->\n    <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n        <div class=\"flex items-center space-x-2.5\">\n            <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-spotgreen-500 to-spotgreen-600 flex items-center justify-center font-extrabold text-navy-950 shadow\">\n                SP\n            </div>\n            <div>\n                <div class=\"text-[11px] text-spotgreen-400 font-semibold tracking-wider uppercase\">NYSE: SPOT · Equity Research</div>\n                <div class=\"text-sm font-bold leading-tight\">Spotify Technology 深度研究报告</div>\n            </div>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n            <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n                <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n            </button>\n            <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n            </button>\n        </div>\n    </header>\n\n    <!-- 移动端折叠抽屉菜单 -->\n    <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n        <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n        <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n            <div>\n                <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n                    <span class=\"font-bold text-white text-base\">SPOT 研报目录导航</span>\n                    <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n                    </button>\n                </div>\n                <ul class=\"mt-4 space-y-1.5 text-sm\">\n                    <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n                    <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n                    <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n                    <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n                    <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n                    <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n                    <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n                </ul>\n            </div>\n            <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n                <p>全球数字娱乐与音频流媒体研究组</p>\n                <p class=\"mt-1\">数据基准：2026年Q3 财报 (Q3 2026)</p>\n            </div>\n        </nav>\n    </div>\n\n    <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n    <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n        <div>\n            <!-- 机构品牌头 -->\n            <div class=\"p-5 border-b border-slate-800/80\">\n                <div class=\"flex items-center space-x-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-spotgreen-500 to-spotgreen-600 flex items-center justify-center text-navy-950 font-extrabold text-base shadow-lg shadow-spotgreen-500/25\">\n                        SPOT\n                    </div>\n                    <div>\n                        <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-spotgreen-400 bg-spotgreen-500/15 px-2 py-0.5 rounded\">NYSE: SPOT</span>\n                        <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Spotify 深度研报</h2>\n                    </div>\n                </div>\n                <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n                    全球音频流媒体霸主 · AI 驱动型全品类音频与创作者平台核心引擎\n                </p>\n            </div>\n\n            <!-- 股票实时快照徽章 -->\n            <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">Q3 2026 总营收</span>\n                    <span class=\"font-mono font-bold text-white\">€5.0B <span class=\"text-spotgreen-400\">(+16% YoY)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">Q4 2026 营收指引</span>\n                    <span class=\"font-mono font-bold text-teal-400\">~€5.2B <span class=\"text-slate-400\">(经营利润 €820M)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n                    <span class=\"text-slate-400\">远期估值锚</span>\n                    <span class=\"font-mono font-bold text-spotgreen-400\">毛利率创新高 33.0%</span>\n                </div>\n            </div>\n\n            <!-- 六个核心章节目录导航 -->\n            <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n                <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n                <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n                    <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-spotgreen-400 mr-2\">00</span>执行摘要与核心指标</span>\n                    </a>\n                    <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n                    </a>\n                    <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n                    </a>\n                    <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n                    </a>\n                    <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n                    </a>\n                    <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n                    </a>\n                    <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n                    </a>\n                </nav>\n            </div>\n        </div>\n\n        <!-- 侧边栏底部工具栏 -->\n        <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n            <div class=\"flex items-center justify-between\">\n                <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n                <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n                    <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n                    <svg class=\"w-3.5 h-3.5 text-spotgreen-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                    <span class=\"dark:hidden\">深色护眼模式</span>\n                    <span class=\"hidden dark:inline\">机构亮色模式</span>\n                </button>\n            </div>\n            <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-spotgreen-500 hover:bg-spotgreen-600 text-navy-950 text-xs font-extrabold transition shadow-sm\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n                <span>打印 / 导出 PDF 研报</span>\n            </button>\n        </div>\n    </aside>\n\n    <!-- 主内容区 -->\n    <main class=\"lg:ml-[280px] min-h-screen\">\n        <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n            <!-- =========================================================\n            00. Hero 研报封面区与执行摘要\n            ========================================================= -->\n            <section id=\"sec-exec\" class=\"scroll-mt-20\">\n                <!-- 顶部研报元数据标签栏 -->\n                <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n                    <div class=\"flex flex-wrap items-center gap-2\">\n                        <span class=\"px-2.5 py-1 rounded-md bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400 font-bold border border-spotgreen-500/30\">评级：强烈买入 / 核心数字娱乐标的</span>\n                        <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 盈利兑现与生态扩张期</span>\n                    </div>\n                    <div class=\"flex items-center space-x-3 font-mono\">\n                        <span>覆盖时间：2026年11月</span>\n                        <span>NYSE: SPOT</span>\n                    </div>\n                </div>\n\n                <!-- Hero 标题卡片 -->\n                <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n                    <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#1DB954 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n                    <div class=\"relative z-10\">\n                        <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-spotgreen-500/20 border border-spotgreen-500/40 text-spotgreen-400 text-xs font-semibold mb-4\">\n                            <span class=\"w-2 h-2 rounded-full bg-spotgreen-400 animate-pulse\"></span>\n                            <span>CORE THESIS · 订阅与 ARPU 双轮驱动毛利率突破 33% 历史新高 × AI 智能推荐与多品类音频生态变现</span>\n                        </div>\n                        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n                            Spotify Technology S.A. (NYSE: SPOT) 深度研究报告：从全球流媒体音频霸主到高利润“AI 驱动型全品类音频与创作者平台”\n                        </h1>\n                        <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n                            Spotify 已成功实现从“烧钱买用户”的传统流媒体向<strong class=\"text-white\">高毛利、强经营杠杆的 AI 驱动型音频与创作者生态巨头</strong>的彻底蜕变。Q3 2026 总营收达到 <strong class=\"text-spotgreen-400\">€5.0B (+16% YoY)</strong>，月活跃用户（MAUs）增至 <strong class=\"text-white\">7.88 亿</strong>，付费订阅用户达到 <strong class=\"text-white\">3.06 亿</strong>。\n                            得益于价格优化与 Marketplace 收入结构改善，季度<strong class=\"text-teal-400\">毛利率飙升至 33.0%</strong> 的历史新高，营业利润达 €6.72 亿（营业利润率 13.5%），自由现金流高达 €7.35 亿。\n                        </p>\n\n                        <!-- 核心投资结论高亮条 -->\n                        <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">毛利率结构性突破</div>\n                                <div class=\"text-white font-semibold\">Q3 毛利率达 33.0%（同比提升 136 bps），Premium 毛利率升至 34.5%</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">卓越经营杠杆释放</div>\n                                <div class=\"text-spotgreen-400 font-semibold\">Q3 营业利润达 €672M（利润率 13.5%），Q4 经营利润指引进一步跃升至 €820M</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">全品类生态加速全球化</div>\n                                <div class=\"text-teal-400 font-semibold\">有声书扩展至超 180 个市场（覆盖超 7.5 亿人），Spotify Partner Program 全球铺开</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 4个核心 KPI 卡片 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n                    <!-- KPI 1 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>Q3 2026 总营收</span>\n                            <span class=\"p-1.5 rounded-lg bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">€4.97B</span>\n                            <span class=\"text-xs font-bold text-spotgreen-600 dark:text-spotgreen-400 bg-spotgreen-500/15 px-2 py-0.5 rounded\">+16% YoY</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            按固定汇率计算同比增长 14%，Premium 收入大增 17% 驱动整体强劲增长。\n                        </p>\n                    </div>\n\n                    <!-- KPI 2 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>月活跃用户 & 付费订阅</span>\n                            <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">306M</span>\n                            <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">MAU 788M</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            付费用户净增 600 万超预期，MAU 同比增长 11% 至 7.88 亿，全球各地区均实现稳健净增。\n                        </p>\n                    </div>\n\n                    <!-- KPI 3 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>毛利率与营业利润</span>\n                            <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">33.0%</span>\n                            <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">€672M 利润</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            毛利率创新高，营业利润率达 13.5%，自由现金流达 €7.35 亿，财务健康度达到历史最佳状态。\n                        </p>\n                    </div>\n\n                    <!-- KPI 4 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>Q4 2026 指引展望</span>\n                            <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">€820M</span>\n                            <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">Q4 经营利润</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            预计 Q4 营收 €5.2B，MAU 达 818M（净增 30M），付费用户达 316M，毛利率进一步攀升至 33.8%。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            一、 业务与收入架构 (Business & Revenue Architecture)\n            ========================================================= -->\n            <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-spotgreen-600 dark:text-spotgreen-400\">Section 01 · Business & Revenue Architecture</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：Premium 订阅与 Ad-Supported 广告双轮驱动</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 2026 总营收 €4.97B · Premium 占比 ~87%</span>\n                </div>\n\n                <!-- 交互式 Chart.js 双视图切换面板 -->\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                    <!-- 左侧：双视图图表 -->\n                    <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n                            <div>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026 营收分部演进与用户规模增长</h3>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">Premium 订阅与 Ad-Supported 广告业务持续双位数稳健增长</p>\n                            </div>\n                            <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                                <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-spotgreen-600 dark:text-spotgreen-400 shadow-sm transition\">视图A：营收结构演进</button>\n                                <button onclick=\"switchBizChart('users')\" id=\"btn-chart-usr\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：MAU与付费用户</button>\n                            </div>\n                        </div>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"bizArchitectureChart\"></canvas>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：结构性拆解核心洞察 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性拐点</h3>\n                            <ul class=\"space-y-4 text-sm\">\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">Premium 订阅收入与 ARPU 双升</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            Q3 Premium 营收同比增长 17%（达 €4.3B 级别），得益于全球定价优化（Pricing Actions）与用户规模扩大，付费用户突破 3.06 亿。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">广告业务（Ad-Supported）自动化兑现</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            Q3 广告收入同比增长 10%（固定汇率下 +9%），由 Spotify Ad Exchange 与自动程序化 biddable 销售渠道的高效放量强力驱动。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">生态拓展：有声书与创作者经济爆发</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            有声书服务在 2026 年底前加速扩展至超过 180 个市场（覆盖超 7.5 亿人），叠加 Spotify Partner Program 与创作者 Memberships，构建高附加值多元变现矩阵。\n                                        </p>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n                            <span class=\"text-slate-500 dark:text-slate-400\">核心利润引擎</span>\n                            <span class=\"font-bold text-spotgreen-600 dark:text-spotgreen-400\">毛利率突破 33.0% 历史大关</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 核心业务板块卡片矩阵 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n                    <!-- 版块 1：Premium 高级订阅服务 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-spotgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n                            <div class=\"flex items-center space-x-2\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400 text-xs font-bold\">核心现金流 · 占收 ~87%</span>\n                                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">+17% YoY</span>\n                            </div>\n                            <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">付费用户：3.06 亿</span>\n                        </div>\n                        <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. Premium 高级订阅服务（Music + Audiobooks）</h3>\n                        <p class=\"mt-3 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            通过多层级定价策略（Individual, Family, Duo, Student）与有声书权益绑定，Q3 付费订阅用户实现全地区净增 600 万。Premium 毛利率进一步攀升至 <strong>34.5%</strong>，得益于收入增长持续超越音乐版权成本（net of marketplace programs）。\n                        </p>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n                            Premium Gross Margin 34.5% (+130 bps YoY) · ARPU 稳健扩张\n                        </div>\n                    </div>\n\n                    <!-- 版块 2：Ad-Supported 免费与广告业务 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n                            <div class=\"flex items-center space-x-2\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">用户漏斗引擎 · 占收 ~13%</span>\n                                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">+10% YoY</span>\n                            </div>\n                            <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">MAU：7.88 亿</span>\n                        </div>\n                        <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. Ad-Supported 广告支持服务（Music & Podcasts）</h3>\n                        <p class=\"mt-3 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            MAU 达到 7.88 亿（同比增长 11%），构建了庞大的付费转化漏斗。广告毛利率显著改善至 <strong>18.7%</strong>（同比提升 105 bps），受益于自动化广告交易所（Ad Exchange）效率优化与播客成本结构持续精简。\n                        </p>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n                            Ad-Supported Gross Margin 18.7% (+105 bps YoY) · 程序化广告驱动\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            二、 行业地位与四重核心护城河 (Industry Position & Moat)\n            ========================================================= -->\n            <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：算法推荐、双边网络与全球化生态</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 全球音频流媒体绝对标杆)</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n                    <!-- 左侧：四重护城河深度解析 -->\n                    <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <!-- 护城河 1 -->\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400 flex items-center justify-center font-bold text-sm\">01</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Taste Profile 与 AI 智能推荐算法</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                推出 Taste Profile (Beta) 功能，让用户直观了解并塑造跨音乐、播客与有声书的个性化推荐偏好。深度学习推荐引擎黏住近 8 亿用户，构筑极高的用户迁移成本与黏性。\n                            </p>\n                        </div>\n\n                        <!-- 护城河 2 -->\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">庞大双边网络效应（创作者 × 听众）</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                汇聚全球数百万艺术家、播客主与作者。通过 Spotify Partner Program 与 Memberships（已扩展至 34+ 市场），为创作者提供多元变现手段，形成飞轮效应。\n                            </p>\n                        </div>\n\n                        <!-- 护城河 3 -->\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全品类音频扩展与有声书全球化壁垒</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                成功将有声书业务从 22 个核心市场迅速拓展至超过 180 个国家和地区（惠及逾 7.5 亿用户），打破传统纯音乐流媒体的天花板，开辟高客单价全品类音频新赛道。\n                            </p>\n                        </div>\n\n                        <!-- 护城河 4 -->\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">卓越的规模化经营杠杆与成本优化</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                过去几年持续优化运营效率、精简播客内容成本结构并与版权方达成精细化 Marketplace 合作，驱动毛利率稳定跨越 33% 关口，营业利润率稳步迈向中高段。\n                            </p>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：五维护城河雷达图 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">音频流媒体五维护城河量化雷达图</h3>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Spotify vs 科技巨头音乐竞品 vs 传统广播/播客平台（满分 10 分）</p>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"moatRadarChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            三、 同行竞争格局横向对比 (Competitive Landscape)\n            ========================================================= -->\n            <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-spotgreen-600 dark:text-spotgreen-400\">Section 03 · Global Competitive Landscape</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：独立音频领跑者 vs 科技巨头生态捆绑</h2>\n                    </div>\n                    <!-- 交互式筛选按钮 -->\n                    <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n                        <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-spotgreen-500 text-navy-950 shadow-sm transition\">全部阵营</button>\n                        <button onclick=\"filterCompetitors('independent')\" data-filter=\"independent\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">独立音频与流媒体</button>\n                        <button onclick=\"filterCompetitors('ecosystem')\" data-filter=\"ecosystem\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">科技巨头硬件/生态捆绑</button>\n                    </div>\n                </div>\n\n                <!-- 横向对比矩阵表格 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n                    <div class=\"overflow-x-auto\">\n                        <table class=\"w-full text-left border-collapse\">\n                            <thead>\n                                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                                    <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心平台</th>\n                                    <th class=\"py-4 px-4 min-w-[130px]\">付费用户/生态定位</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">产品矩阵与内容丰富度</th>\n                                    <th class=\"py-4 px-4 min-w-[135px]\">毛利率与盈利模式</th>\n                                    <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与差异化评估</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                                <!-- 行 1：Spotify 基准 -->\n                                <tr data-category=\"independent\" class=\"bg-spotgreen-500/5 dark:bg-spotgreen-500/10 font-medium\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"flex items-center space-x-2\">\n                                            <span class=\"px-2 py-0.5 rounded bg-spotgreen-500 text-navy-950 text-[10px] font-extrabold\">行业绝对龙头</span>\n                                            <span class=\"font-bold text-slate-900 dark:text-white\">Spotify (SPOT)</span>\n                                        </div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球音频流媒体与创作者平台</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">3.06亿付费 / 7.88亿MAU</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">音乐 + 播客 + 有声书 (180+市场)</td>\n                                    <td class=\"py-4 px-4 font-mono font-bold text-spotgreen-600 dark:text-spotgreen-400\">~33.0% (创新高)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>独立音频霸主：</strong>跨平台无缝体验与顶级 AI 推荐，毛利率与经营杠杆持续超预期释放。\n                                    </td>\n                                </tr>\n\n                                <!-- 行 2：Apple Music -->\n                                <tr data-category=\"ecosystem\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">Apple Music (AAPL)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">iOS生态硬件捆绑服务</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">估算 ~90M-100M 付费用户</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">无损音乐 + 空间音频为主</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">未独立披露 (服务板块高利)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>生态协同强：</strong>深度集成 Apple 硬件生态，但缺乏 Spotify 的跨平台社交分享属性及强大的免费广告漏斗。\n                                    </td>\n                                </tr>\n\n                                <!-- 行 3：YouTube Music -->\n                                <tr data-category=\"ecosystem\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">YouTube Music / Premium (GOOGL)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">视频+音频双栖流量转化</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">依托 YouTube 庞大会员体系</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">音乐流媒体 + 独家视频混剪</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">平台级广告与订阅利润</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>视频引流优势：</strong>背靠全球最大视频平台，视听转换效率极高，但在独立音频深度社区经营上略逊一筹。\n                                    </td>\n                                </tr>\n\n                                <!-- 行 4：Amazon Music -->\n                                <tr data-category=\"ecosystem\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">Amazon Music (AMZN)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Prime 会员打包权益</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">依托 Prime 庞大订阅底盘</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">音乐 + Wondery 播客网络</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">电商/会员生态附属服务</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>打包促销为主：</strong>通过 Echo 智能音箱与 Prime 会员渗透，但独立付费意愿与用户粘性相对分散。\n                                    </td>\n                                </tr>\n\n                                <!-- 行 5：Tencent Music (TME) -->\n                                <tr data-category=\"independent\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">Tencent Music 腾讯音乐 (TME)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">中国市场流媒体龙头</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">超 1 亿中国本土付费会员</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">在线音乐 + 社交娱乐/直播</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高毛利音乐会员订阅驱动</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>亚太市场主导：</strong>在中国本土具有绝对版权与粉丝经济优势，与 Spotify 在国际化全球版图上形成错位竞争。\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- 配套 Chart.js 横向条形图：毛利率与营业利润率对比 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要音频与数字娱乐平台盈利能力对比（Gross & Operating Margins）</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">Spotify Q3 毛利率攀升至 33.0%，经营利润率达 13.5%，盈利结构持续向健康成熟期跃升</p>\n                        </div>\n                        <span class=\"text-xs font-semibold text-spotgreen-600 dark:text-spotgreen-400 bg-spotgreen-500/15 px-2.5 py-1 rounded\">经营杠杆驱动利润率超预期释放</span>\n                    </div>\n                    <div class=\"relative h-60 w-full\">\n                        <canvas id=\"compMarginChart\"></canvas>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n            ========================================================= -->\n            <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：毛利率历史新高与强劲现金流支撑</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">自由现金流 €735M · 流动性储备 €9.9B</span>\n                </div>\n\n                <!-- 1. 财务健康度四大硬核指标卡 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-spotgreen-600 dark:text-spotgreen-400 uppercase\">Gross Margin</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">33.0%</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            Q3 创下历史新高，同比大幅提升 136 bps，Premium 订阅与广告业务双向毛利改善成果显著。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Income</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">€672M</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            营业利润率达到 13.5%，Q4 进一步指引至 €820M，展现出卓越的规模化经营杠杆兑现能力。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Free Cash Flow</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">€735M</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            Q3 自由现金流高达 €7.35 亿，流动性与资产负债表极其稳健，现金及短投总额达 €9.9B。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Share Repurchase</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$1.1B</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            年初至 10 月中旬已累计回购 220 万股计 $1.1 亿美元，积极通过股份回购回报长期股东。\n                        </p>\n                    </div>\n                </div>\n\n                <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026 营收、经营利润与毛利率演进趋势</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">从低利润规模扩张到盈利爆发：营收稳步攀升与毛利率突破 33% 形成强劲戴维斯双击</p>\n                        </div>\n                        <span class=\"text-xs font-mono font-bold text-spotgreen-600 dark:text-spotgreen-400 bg-spotgreen-500/10 px-2.5 py-1 rounded\">Q4 经营利润指引 €820M</span>\n                    </div>\n                    <div class=\"relative h-72 w-full\">\n                        <canvas id=\"valEvolutionChart\"></canvas>\n                    </div>\n                </div>\n\n                <!-- 3. 互动式 ARPU 提价与经营杠杆复利推演器 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n                        <div>\n                            <h3 class=\"text-lg font-bold text-white\">Spotify (SPOT) 投资回报与 ARPU 复利推演器</h3>\n                            <p class=\"text-xs text-slate-400 mt-1\">模拟付费用户增长、ARPU 提价与毛利率持续改善下的长期持仓市值与现金流回报</p>\n                        </div>\n                        <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-spotgreen-300 border border-slate-700\">交互式推演模型</span>\n                    </div>\n\n                    <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n                        <div class=\"space-y-5\">\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n                                    <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n                                </div>\n                                <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-spotgreen-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">持有年限 (Years)</span>\n                                    <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n                                </div>\n                                <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-spotgreen-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">预期年化营收/盈利增速</span>\n                                    <span id=\"grVal\" class=\"font-bold text-spotgreen-400\">15.0%</span>\n                                </div>\n                                <input id=\"grSlider\" type=\"range\" min=\"5\" max=\"30\" step=\"1\" value=\"15\" class=\"w-full accent-spotgreen-400 cursor-pointer\">\n                            </div>\n                        </div>\n\n                        <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n                                <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$30,452</div>\n                                <div id=\"totalGainPct\" class=\"text-xs text-spotgreen-400 mt-1\">累计总回报 +52.3%</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末对应隐含股价</div>\n                                <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$885.00</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">基于经营杠杆与估值重估</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n                                <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">15.0%</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">主营业务盈利强劲增长</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            五、 投资决策与风险配置框架 (Investment Decision & Risk)\n            ========================================================= -->\n            <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-spotgreen-600 dark:text-spotgreen-400\">Section 05 · Investment Decision & Risk Allocation</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：数字娱乐与科技成长组合核心持仓</span>\n                </div>\n\n                <!-- 1. 三情景估值推演卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <!-- 牛市情景 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-spotgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-spotgreen-600 dark:text-spotgreen-400\">概率：30%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">毛利率目标：35%+</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>有声书全球 180+ 市场渗透超预期，广告业务全面爆发，MAU 加速突破 9 亿，毛利率稳步站上 35%，营业利润率向 18% 迈进。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-spotgreen-600 dark:text-spotgreen-400\">\n                            潜在上行空间：+40% 至 +55%\n                        </div>\n                    </div>\n\n                    <!-- 基准情景 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">毛利率目标：33%–34%</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>Q4 指引顺利兑现（MAU 818M，付费用户 316M，经营利润 €820M），ARPU 温和提价，自由现金流稳定在 €3B+ 级别。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n                            潜在上行空间：+15% 至 +25%\n                        </div>\n                    </div>\n\n                    <!-- 熊市情景 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">毛利率目标：31%以下</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>宏观消费疲软导致付费用户净增放缓，版权成本或云/AI 营销费用超预期上升，广告市场复苏不及预期。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                            潜在下行回撤：-15% 至 -25%\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 2. 四大核心风险评估矩阵 -->\n                <div>\n                    <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 版权成本与分成压力</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">音乐厂牌与版权方溢价能力</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                音乐版权成本占 Spotify 营收大头，若唱片公司未来联合提高分成比例，可能对毛利率形成阶段性挤压，需依靠 Marketplace 广告及有声书高毛利品类对冲。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 宏观广告需求波动风险</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">广告预算受宏观周期扰动</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                尽管 Ad-Supported 广告收入稳健增长，但在全球宏观经济波动期，品牌广告主的数字营销预算可能出现阶段性缩减。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 科技巨头生态竞争风险</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Apple / Amazon / YouTube 生态捆绑</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                拥有底层硬件与操作系统优势的科技巨头可能加大对音乐流媒体的打包促销力度，对 Spotify 的增量用户获取构成一定竞争牵制。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 汇率波动与合规摩擦</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：低中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">欧元/美元及全球多地应用商店合规</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                跨国经营涉及多币种汇兑损益，同时在欧盟及美洲面临关于应用商店支付反垄断与税费合规的持续监管动态。\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n            ========================================================= -->\n            <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n                    </div>\n                    <div class=\"flex items-center space-x-2 no-print\">\n                        <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-spotgreen-500/15 text-spotgreen-600 dark:text-spotgreen-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n                        <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n                        点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n                    </p>\n\n                    <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n                        <!-- KPI 1 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#1DB954] focus:ring-spotgreen-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 付费订阅用户能否稳健达成 Q4 3.16 亿指引</span>\n                                    <span class=\"text-[11px] font-mono text-spotgreen-600 dark:text-spotgreen-400 font-semibold shrink-0\">订阅基本盘</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    追踪每季全球净增表现（Q3 实际达 3.06 亿，Q4 预计净增 1000 万达 3.16 亿），验证全球渗透韧性。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 2 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#1DB954] focus:ring-spotgreen-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 毛利率能否稳居 33% 并在 Q4 进一步升至 33.8%</span>\n                                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">盈利结构晴雨表</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控 Premium 与 Ad-Supported 各板块毛利率走势，确认 Marketplace 与有声书成本结构优化成效。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 3 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#1DB954] focus:ring-spotgreen-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. MAU 月活用户冲刺 8.18 亿与漏斗转化率</span>\n                                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">用户增长引擎</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    观察 Q4 预计净增 3000 万至 8.18 亿的达成情况，评估新兴市场（如印度等 14 亿人口大国）扩张势能。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 4 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#1DB954] focus:ring-spotgreen-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 经营利润兑现情况（Q4 目标 €820M）</span>\n                                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">经营杠杆验证</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    核查 Q4 经营利润指引 €820M 是否顺利兑现，确保营销及云/AI 开支增速得到有效控制。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 5 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#1DB954] focus:ring-spotgreen-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 有声书扩展至 180+ 市场的商业化变现进展</span>\n                                    <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">全品类第二曲线</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    追踪有声书在超过 180 个市场铺开后的用户收听时长、单独购买转化率及对整体 ARPU 的实际增厚效果。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 6 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#1DB954] focus:ring-spotgreen-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 创作者生态（Spotify Partner Program / Memberships）扩张</span>\n                                    <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">创作者经济</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    关注 Partner Program 扩展至 35+ 新市场及粉丝 Memberships 在 34+ 市场的采纳率与广告吸附力。\n                                </p>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            页脚免责声明 (Disclaimer Footer)\n            ========================================================= -->\n            <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n                <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n                    <span>Spotify Technology S.A. (NYSE: SPOT) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n                    <span>数据基准：2026年Q3 财报及最新市场一致预期</span>\n                </div>\n                <p class=\"leading-relaxed\">\n                    <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、财报电话会议纪要及市场公开一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n                </p>\n            </footer>\n\n        </div>\n    </main>\n\n    <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n    <script>\n    function toggleTheme() {\n        const html = document.documentElement;\n        html.classList.toggle('dark');\n        updateChartsTheme();\n    }\n\n    function toggleMobileMenu() {\n        const drawer = document.getElementById('mobile-drawer');\n        drawer.classList.toggle('hidden');\n    }\n\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n        const scrollTop = window.scrollY;\n        const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n        const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n        document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n        let currentId = 'sec-exec';\n        sections.forEach(sec => {\n            const top = sec.offsetTop - 160;\n            if (scrollTop >= top) {\n                currentId = sec.getAttribute('id');\n            }\n        });\n\n        navLinks.forEach(link => {\n            link.classList.remove('active');\n            const numSpan = link.querySelector('span span');\n            if (numSpan) {\n                numSpan.classList.remove('text-spotgreen-400');\n                numSpan.classList.add('text-slate-500');\n            }\n            if (link.dataset.target === currentId) {\n                link.classList.add('active');\n                if (numSpan) {\n                    numSpan.classList.remove('text-slate-500');\n                    numSpan.classList.add('text-spotgreen-400');\n                }\n            }\n        });\n    });\n\n    function filterCompetitors(category) {\n        document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n            if (btn.dataset.filter === category) {\n                btn.classList.add('bg-spotgreen-500', 'text-navy-950', 'font-semibold', 'shadow-sm');\n                btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            } else {\n                btn.classList.remove('bg-spotgreen-500', 'text-navy-950', 'font-semibold', 'shadow-sm');\n                btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            }\n        });\n\n        const rows = document.querySelectorAll('#comp-table-body tr');\n        rows.forEach(row => {\n            const rowCat = row.dataset.category;\n            if (category === 'all' || rowCat === category) {\n                row.style.display = '';\n            } else {\n                row.style.display = 'none';\n            }\n        });\n    }\n\n    const KPI_STORAGE_KEY = 'spot_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n        try {\n            const saved = localStorage.getItem(KPI_STORAGE_KEY);\n            if (saved) {\n                const stateMap = JSON.parse(saved);\n                document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                    if (typeof stateMap[cb.id] === 'boolean') {\n                        cb.checked = stateMap[cb.id];\n                    }\n                });\n            }\n        } catch (e) {}\n        updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n        const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n        const total = checkboxes.length;\n        let checkedCount = 0;\n        const stateMap = {};\n\n        checkboxes.forEach(cb => {\n            stateMap[cb.id] = cb.checked;\n            if (cb.checked) checkedCount++;\n        });\n\n        const pct = Math.round((checkedCount / total) * 100);\n        document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n        try {\n            localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n        } catch (e) {}\n    }\n\n    function resetKpiChecklist() {\n        document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            cb.checked = false;\n        });\n        updateKpiChecklist();\n    }\n\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'revenue';\n\n    function getChartColors() {\n        const isDark = document.documentElement.classList.contains('dark');\n        return {\n            text: isDark ? '#CBD5E1' : '#475569',\n            grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n            radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n        };\n    }\n\n    function initBizChart() {\n        const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n        const colors = getChartColors();\n\n        const revConfig = {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', 'Q3 2026', 'Q4 2026(E)'],\n                datasets: [\n                    {\n                        label: 'Premium 订阅营收 (€B)',\n                        data: [11.7, 13.5, 15.8, 4.30, 4.50],\n                        backgroundColor: '#1DB954',\n                        borderRadius: 4,\n                    },\n                    {\n                        label: 'Ad-Supported 广告营收 (€B)',\n                        data: [1.6, 1.8, 2.0, 0.67, 0.70],\n                        backgroundColor: '#3B82F6',\n                        borderRadius: 4,\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: €${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        stacked: true,\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        stacked: true,\n                        max: 6.0,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '€' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        const usrConfig = {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', 'Q3 2026', 'Q4 2026(E)'],\n                datasets: [\n                    {\n                        label: '月活跃用户 MAU (Million)',\n                        data: [602, 675, 730, 788, 818],\n                        backgroundColor: '#06B6D4',\n                        borderRadius: 6,\n                        barThickness: 26\n                    },\n                    {\n                        label: '付费订阅用户 Subscribers (Million)',\n                        data: [236, 268, 290, 306, 316],\n                        backgroundColor: '#1DB954',\n                        borderRadius: 6,\n                        barThickness: 26\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.y}M`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        max: 900,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + 'M' }\n                    }\n                }\n            }\n        };\n\n        if (bizChartInstance) bizChartInstance.destroy();\n        bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : usrConfig);\n    }\n\n    function switchBizChart(mode) {\n        currentBizMode = mode;\n        const btnRev = document.getElementById('btn-chart-rev');\n        const btnUsr = document.getElementById('btn-chart-usr');\n        const titleEl = document.getElementById('biz-chart-title');\n        const subEl = document.getElementById('biz-chart-sub');\n\n        if (mode === 'revenue') {\n            btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-spotgreen-600 dark:text-spotgreen-400 shadow-sm transition';\n            btnUsr.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '2023–2026 营收分部演进与广告/订阅结构';\n            subEl.textContent = 'Premium 订阅与 Ad-Supported 广告业务持续双位数稳健增长';\n        } else {\n            btnUsr.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-spotgreen-600 dark:text-spotgreen-400 shadow-sm transition';\n            btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '2023–2026 MAU 活跃用户与付费订阅用户规模演进';\n            subEl.textContent = 'MAU 稳步向 8.18 亿冲刺，付费用户突破 3.06 亿';\n        }\n        initBizChart();\n    }\n\n    function initRadarChart() {\n        const ctx = document.getElementById('moatRadarChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (radarChartInstance) radarChartInstance.destroy();\n        radarChartInstance = new Chart(ctx, {\n            type: 'radar',\n            data: {\n                labels: [\n                    '算法推荐与 Taste Profile 黏性',\n                    '创作者生态与双边网络效应',\n                    '全品类音频扩展 (有声书/播客)',\n                    '规模化经营杠杆与毛利优化',\n                    '跨平台无缝生态与品牌心智'\n                ],\n                datasets: [\n                    {\n                        label: 'Spotify (SPOT)',\n                        data: [9.8, 9.5, 9.6, 9.2, 9.7],\n                        borderColor: '#1DB954',\n                        backgroundColor: 'rgba(29, 185, 84, 0.22)',\n                        pointBackgroundColor: '#1DB954',\n                        borderWidth: 2.5\n                    },\n                    {\n                        label: '科技巨头音乐竞品 (Apple/Amazon)',\n                        data: [7.5, 6.8, 7.0, 8.5, 8.0],\n                        borderColor: '#3B82F6',\n                        backgroundColor: 'rgba(59, 130, 246, 0.14)',\n                        pointBackgroundColor: '#3B82F6',\n                        borderWidth: 1.8\n                    },\n                    {\n                        label: '传统广播与独立播客平台',\n                        data: [5.0, 6.0, 5.5, 6.0, 5.2],\n                        borderColor: '#94A3B8',\n                        backgroundColor: 'rgba(148, 163, 184, 0.12)',\n                        pointBackgroundColor: '#94A3B8',\n                        borderWidth: 1.5,\n                        borderDash: [4, 4]\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n                    }\n                },\n                scales: {\n                    r: {\n                        min: 0,\n                        max: 10,\n                        ticks: { display: false, stepSize: 2 },\n                        grid: { color: colors.grid },\n                        angleLines: { color: colors.radarAngle },\n                        pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initCompMarginChart() {\n        const ctx = document.getElementById('compMarginChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (compMarginChartInstance) compMarginChartInstance.destroy();\n        compMarginChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: [\n                    'Spotify (SPOT · 音频流媒体霸主)',\n                    'Tencent Music 腾讯音乐 (TME)',\n                    'Alphabet / YouTube Music (GOOGL)',\n                    'Apple Music (AAPL · 生态服务)',\n                    'Amazon Music (AMZN · Prime打包)'\n                ],\n                datasets: [{\n                    label: '毛利率 Gross Margin (%)',\n                    data: [33.0, 39.5, 35.0, 32.0, 26.5],\n                    backgroundColor: [\n                        '#1DB954',\n                        '#3B82F6',\n                        '#06B6D4',\n                        '#64748B',\n                        '#94A3B8'\n                    ],\n                    borderRadius: 6,\n                    barThickness: 22\n                }]\n            },\n            options: {\n                indexAxis: 'y',\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `毛利率: ${ctx.parsed.x}%`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        max: 50,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    },\n                    y: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initValEvolutionChart() {\n        const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n        valEvolutionChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', 'Q3 2026', 'Q4 2026(E)'],\n                datasets: [\n                    {\n                        type: 'bar',\n                        label: '全年/季度总营收 (€B)',\n                        data: [13.2, 15.3, 17.8, 4.97, 5.20],\n                        backgroundColor: 'rgba(29, 185, 84, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 24,\n                        yAxisID: 'y'\n                    },\n                    {\n                        type: 'bar',\n                        label: '经营利润 Operating Income (€M)',\n                        data: [114, 1140, 1450, 672, 820],\n                        backgroundColor: 'rgba(59, 130, 246, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 24,\n                        yAxisID: 'y1'\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => ctx.dataset.yAxisID === 'y'\n                                ? `${ctx.dataset.label}: €${ctx.parsed.y}B`\n                                : `${ctx.dataset.label}: €${ctx.parsed.y}M`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        type: 'linear',\n                        position: 'left',\n                        max: 6.5,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '€' + v + 'B' }\n                    },\n                    y1: {\n                        type: 'linear',\n                        position: 'right',\n                        min: 0,\n                        max: 1000,\n                        grid: { drawOnChartArea: false },\n                        ticks: { color: '#3B82F6', font: { size: 11, weight: '600' }, callback: v => '€' + v + 'M' }\n                    }\n                }\n            }\n        });\n    }\n\n    function updateChartsTheme() {\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n    }\n\n    // Calculator Logic\n    const invSlider = document.getElementById('invSlider');\n    const yrSlider = document.getElementById('yrSlider');\n    const grSlider = document.getElementById('grSlider');\n\n    function updateCalculator() {\n        const principal = parseFloat(invSlider.value);\n        const years = parseInt(yrSlider.value);\n        const growthRate = parseFloat(grSlider.value) / 100;\n\n        document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n        document.getElementById('yrVal').textContent = years + ' 年';\n        document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n        const finalVal = principal * Math.pow(1 + growthRate, years);\n        const totalGain = finalVal - principal;\n        const gainPct = (totalGain / principal) * 100;\n        const impliedPrice = 580 * Math.pow(1 + growthRate * 0.8, years);\n\n        document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n        document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n        document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n        document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n    }\n\n    [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n    window.addEventListener('DOMContentLoaded', () => {\n        loadKpiChecklist();\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n        updateCalculator();\n    });\n    </script>\n</body>\n</html>\n"};
